/* Original LBH Dakwah & Pendidikan artwork supplied by Muhammad Subhi. */
(()=>{
 const t=(id,en)=>document.documentElement.lang==='en'?en:id;
 const media='assets/content-lbhdp/';
 let format='all',selected=0,slide=0,project,host,opener,swipeUntil=0;
 const items=()=>project?.contentManagement?.items||[];
 const filtered=()=>items().filter(x=>format==='all'||x.format===format);
 const art=item=>`<div class="content-original"><img src="${media+esc(item.slides[slide])}" alt="${esc(t(...item.name))} · ${t('Halaman','Page')} ${slide+1} / ${item.slides.length}" width="1122" height="1402" decoding="async"></div>`;
 const dialog=document.createElement('dialog');dialog.className='content-dialog';dialog.setAttribute('aria-labelledby','content-dialog-title');document.body.append(dialog);
 function navigation(item){return `<div class="content-slide-nav"><button data-slide="-1" ${item.slides.length<2?'disabled':''} aria-label="${t('Slide sebelumnya','Previous slide')}">←</button><span aria-live="polite">${t('Halaman','Page')} ${slide+1} / ${item.slides.length}</span><button data-slide="1" ${item.slides.length<2?'disabled':''} aria-label="${t('Slide berikutnya','Next slide')}">→</button></div>`}
 function draw(){
  if(!host||!project)return;const list=filtered(),item=list[selected];if(!item)return;
  const cm=project.contentManagement,kind=item.format==='carousel'?'Carousel':t('Feed tunggal','Single feed');
  host.innerHTML=`<div class="content-heading"><div><span class="eyebrow">${t('KOLEKSI KONTEN / LBHDP','CONTENT COLLECTION / LBHDP')}</span><h2>LBH Dakwah &amp; Pendidikan</h2></div><span class="content-demo-badge">${items().length} ${t('KOLEKSI','COLLECTIONS')} · ${items().reduce((n,x)=>n+x.slides.length,0)} ${t('HALAMAN','PAGES')}</span></div><p class="content-demo-notice">${t('Penugasan berjalan: Oktober 2026–Maret 2027. Mengelola website, panel admin, Instagram, dan Facebook.','Ongoing engagement: October 2026–March 2027. Managing the website, admin panel, Instagram, and Facebook.')}</p><div class="content-formats" role="group" aria-label="${t('Pilih format konten','Choose content format')}">${[['all','Semua koleksi','All collections'],['carousel','Carousel','Carousel'],['single','Feed tunggal','Single feed']].map(([key,id,en])=>`<button data-content-format="${key}" aria-pressed="${format===key}">${t(id,en)}</button>`).join('')}</div><div class="content-layout"><div class="content-stage"><div class="content-stage-top"><span>${kind} · 4:5</span><span>${String(selected+1).padStart(2,'0')} / ${String(list.length).padStart(2,'0')}</span></div><button class="content-open" aria-label="${t('Perbesar karya','Enlarge artwork')}">${art(item)}</button>${navigation(item)}<button class="content-zoom">${t('Perbesar karya','Enlarge artwork')} ↗</button><div class="content-thumbs" role="group" aria-label="${t('Pilih karya','Choose artwork')}">${list.map((x,i)=>`<button data-content-item="${i}" aria-pressed="${i===selected}"><img src="${media+esc(x.slides[0])}" alt="" loading="lazy"><span>${esc(t(...x.name))}</span><small>${x.slides.length} ${t('halaman','pages')}</small></button>`).join('')}</div></div><aside class="content-info"><span class="eyebrow">${t('DI BALIK KONTEN','BEHIND THE CONTENT')}</span><h3>${esc(t(...item.name))}</h3><dl><div><dt>${t('Pilar konten','Content pillar')}</dt><dd>${esc(t(...item.pillar))}</dd></div><div><dt>${t('Format','Format')}</dt><dd>${kind} · ${item.slides.length} ${t('halaman','pages')}</dd></div><div><dt>${t('Kanal yang dikelola','Managed channels')}</dt><dd>Website · ${t('Panel admin','Admin panel')} · Instagram · Facebook</dd></div></dl>${item.caption?`<div class="content-caption"><small>CAPTION</small><p>${esc(item.caption)}</p></div>`:''}<div class="content-scope"><small>${t('KONTRIBUSI MUHAMMAD SUBHI','MUHAMMAD SUBHI’S CONTRIBUTION')}</small><h4>${esc(cm.role)}</h4><ul>${(document.documentElement.lang==='en'?cm.enScope:cm.scope).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><details class="campaign-details"><summary>${t('Di Balik Kampanye','Behind the Campaign')} <span>+</span></summary><ol><li><b>${t('Strategi','Strategy')}</b><p>${t('Brand guideline, pilar konten, dan kalender konten.','Brand guidelines, content pillars and editorial calendar.')}</p></li><li><b>${t('Produksi','Production')}</b><p>${t('Desain dan caption yang menjaga identitas lembaga.','Design and captions maintaining the institution’s identity.')}</p></li><li><b>${t('Distribusi & pengelolaan','Distribution & management')}</b><p>${t('Publikasi, mirroring, integrasi akun, serta pengelolaan website, panel admin, Instagram, dan Facebook.','Publishing, cross-posting, account integration, and management of the website, admin panel, Instagram, and Facebook.')}</p></li></ol></details></aside></div>`;
 }
 function drawDialog(){const item=filtered()[selected];dialog.innerHTML=`<button class="content-dialog-close" aria-label="${t('Tutup karya','Close artwork')}">×</button><h2 id="content-dialog-title">${esc(t(...item.name))}</h2><div class="content-dialog-art">${art(item)}</div>${navigation(item)}`}
 function open(){opener=document.activeElement;drawDialog();dialog.showModal();dialog.querySelector('.content-dialog-close').focus()}
 function close(){dialog.close();(opener?.isConnected?opener:host?.querySelector('.content-open'))?.focus({preventScroll:true})}
 function move(n){const count=filtered()[selected].slides.length;slide=(slide+n+count)%count;draw();if(dialog.open){const direction=document.activeElement?.dataset?.slide;drawDialog();dialog.querySelector(direction?`[data-slide="${direction}"]`:'.content-dialog-close')?.focus({preventScroll:true})}}
 dialog.addEventListener('click',e=>{const s=e.target.closest('[data-slide]');if(s){const value=s.dataset.slide;move(+value);dialog.querySelector(`[data-slide="${value}"]`)?.focus();return}if(e.target===dialog||e.target.closest('.content-dialog-close'))close()});dialog.addEventListener('cancel',e=>{e.preventDefault();close()});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}});
 window.renderContentGallery=p=>{project=p;if(!host){host=document.createElement('section');host.id='content-gallery';host.className='content-gallery';host.setAttribute('aria-label','LBH Dakwah & Pendidikan — Content Collection');document.querySelector('[data-screen="portofolio"] .project').before(host);host.addEventListener('click',e=>{if(Date.now()<swipeUntil)return;const f=e.target.closest('[data-content-format]'),i=e.target.closest('[data-content-item]'),s=e.target.closest('[data-slide]');if(f){format=f.dataset.contentFormat;selected=0;slide=0;draw();host.querySelector(`[data-content-format="${format}"]`)?.focus({preventScroll:true})}else if(i){selected=+i.dataset.contentItem;slide=0;draw();host.querySelector(`[data-content-item="${selected}"]`)?.focus({preventScroll:true})}else if(s){const value=s.dataset.slide;move(+value);host.querySelector(`[data-slide="${value}"]`)?.focus({preventScroll:true})}else if(e.target.closest('.content-open,.content-zoom'))open()});let x,y;host.addEventListener('pointerdown',e=>{if(e.target.closest('.content-open')){x=e.clientX;y=e.clientY}});host.addEventListener('pointerup',e=>{if(x==null)return;if(Math.abs(e.clientX-x)>45&&Math.abs(e.clientY-y)<60){swipeUntil=Date.now()+350;move(e.clientX<x?1:-1)}x=null});host.addEventListener('pointercancel',()=>{x=null})}host.hidden=false;draw()};
 window.addEventListener('languagechange',()=>{draw();if(dialog.open)close()});
 if(new URLSearchParams(location.search).get('view')==='content'){filter='social';active=projects.findIndex(p=>p.contentManagement);document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter==='social');b.setAttribute('aria-pressed',String(b.dataset.filter==='social'))});if(location.hash==='#portofolio')render()}
})();
